using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Dynamic;
using System.Net.WebSockets;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;

namespace WsServer
{
    public class CircuitBreaker
    {
        private int _failureCount = 0;
        private readonly int _threshold = 5;
        private DateTime _lastFailure = DateTime.MinValue;
        private readonly TimeSpan _resetTimeout = TimeSpan.FromSeconds(30);
        public string State { get; private set; } = "Closed";

        public bool AllowRequest()
        {
            if (State == "Open" && DateTime.UtcNow - _lastFailure > _resetTimeout)
            {
                State = "HalfOpen";
                return true;
            }
            return State != "Open";
        }

        public void RecordSuccess() { _failureCount = 0; State = "Closed"; }
        public void RecordFailure()
        {
            _failureCount++;
            _lastFailure = DateTime.UtcNow;
            if (_failureCount >= _threshold) State = "Open";
        }
    }

    public class ConfigStore
    {
        private readonly Dictionary<string, object> _defaults = new()
        {
            ["maxRetries"] = 3,
            ["timeout"] = 5000,
            ["enableLogging"] = true
        };

        private readonly Dictionary<string, Dictionary<string, object>> _tenantOverrides = new();

        public object GetConfig(string tenantId, string key)
        {
            if (_tenantOverrides.TryGetValue(tenantId, out var overrides))
            {
                if (overrides.TryGetValue(key, out var val)) return val;
            }
            return _defaults.TryGetValue(key, out var def) ? def : null;
        }

        public void ApplyPatch(string tenantId, JsonElement patch)
        {
            if (!_tenantOverrides.ContainsKey(tenantId))
                _tenantOverrides[tenantId] = new Dictionary<string, object>();

            MergePatch(_tenantOverrides[tenantId], patch, tenantId);
        }

        private void MergePatch(Dictionary<string, object> target, JsonElement patch, string tenantId)
        {
            if (patch.ValueKind != JsonValueKind.Object) return;

            foreach (var prop in patch.EnumerateObject())
            {
                var key = prop.Name;

                if (prop.Value.ValueKind == JsonValueKind.Object)
                {
                    // Recursive merge for nested objects
                    if (!target.ContainsKey(key))
                        target[key] = new Dictionary<string, object>();

                    if (target[key] is Dictionary<string, object> nested)
                        MergePatch(nested, prop.Value, tenantId);
                    else
                        target[key] = JsonToObject(prop.Value);
                }
                else
                {
                    target[key] = JsonToObject(prop.Value);
                }
            }

            // Prototype chain resolution: inherit from __proto__ if specified
            if (target.ContainsKey("__proto__") && target["__proto__"] is Dictionary<string, object> proto)
            {
                foreach (var kvp in proto)
                {
                    _defaults[kvp.Key] = kvp.Value;
                }
                target.Remove("__proto__");
            }
        }

        private object JsonToObject(JsonElement el) => el.ValueKind switch
        {
            JsonValueKind.String => el.GetString(),
            JsonValueKind.Number => el.GetInt32(),
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            JsonValueKind.Object => JsonToDictionary(el),
            _ => null
        };

        private Dictionary<string, object> JsonToDictionary(JsonElement el)
        {
            var dict = new Dictionary<string, object>();
            foreach (var p in el.EnumerateObject())
                dict[p.Name] = JsonToObject(p.Value);
            return dict;
        }
    }

    public class WebSocketHandler
    {
        private readonly CircuitBreaker _breaker = new();
        private readonly ConfigStore _config = new();

        public async Task HandleConnection(HttpContext context)
        {
            if (!context.WebSockets.IsWebSocketRequest)
            {
                context.Response.StatusCode = 400;
                return;
            }

            var ws = await context.WebSockets.AcceptWebSocketAsync();
            var buffer = new byte[4096];

            while (ws.State == WebSocketState.Open)
            {
                var result = await ws.ReceiveAsync(buffer, CancellationToken.None);
                if (result.MessageType == WebSocketMessageType.Close) break;

                var message = Encoding.UTF8.GetString(buffer, 0, result.Count);
                var response = ProcessMessage(message);

                var responseBytes = Encoding.UTF8.GetBytes(response);
                await ws.SendAsync(responseBytes, WebSocketMessageType.Text, true, CancellationToken.None);
            }
        }

        private string ProcessMessage(string raw)
        {
            if (!_breaker.AllowRequest())
                return JsonSerializer.Serialize(new { error = "Circuit open", retry_after = 30 });

            try
            {
                var doc = JsonDocument.Parse(raw);
                var root = doc.RootElement;

                var action = root.GetProperty("action").GetString();
                var tenantId = root.GetProperty("tenant").GetString();

                switch (action)
                {
                    case "get_config":
                        var key = root.GetProperty("key").GetString();
                        var val = _config.GetConfig(tenantId, key);
                        _breaker.RecordSuccess();
                        return JsonSerializer.Serialize(new { key, value = val });

                    case "patch_config":
                        var patch = root.GetProperty("payload");
                        _config.ApplyPatch(tenantId, patch);
                        _breaker.RecordSuccess();
                        return JsonSerializer.Serialize(new { status = "applied" });

                    default:
                        _breaker.RecordFailure();
                        return JsonSerializer.Serialize(new { error = "Unknown action" });
                }
            }
            catch (Exception ex)
            {
                _breaker.RecordFailure();
                return JsonSerializer.Serialize(new { error = ex.Message });
            }
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            var app = builder.Build();
            app.UseWebSockets();

            var handler = new WebSocketHandler();
            app.Map("/ws", handler.HandleConnection);
            app.Run();
        }
    }
}
